gr=dict(t='Grammar – Modal verbs', p=[
 'Modal verbs are helping verbs used before the main verb: can, could, may, might, shall, should, will, would, must, ought to.',
 'Ability – can: You can learn a lot.',
 'Possibility – may / might: It might rain later today.',
 'Necessity / obligation – must: I must finish this report by tomorrow.',
 'Moral obligation – ought to: You ought to apologise.',
 'Advice / suggestion – should, could: You should consider all the pros and cons.',
 'Permission – may, can, could: May I leave early today?',
 'Polite request – would, could: Could you pass the salt, please?',
 'Sensory words: see – panorama, glimpse; hear – music, strains; smell – perfume; taste – relish, morsel; feel – rough, smooth, shaggy, quiver.']),
